{
  "contract": "X7RLiquidityHub",
  "closure": {
    "site_function": "sendTreasuryBalance",
    "site_call": ".call",
    "functions": [
      "<fallback>",
      "processFees",
      "sendDistributeBalance",
      "sendTreasuryBalance"
    ],
    "justification": "Includes all functions that can be reached during the callback window and affect the exposed storage variables."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>",
      "processFees",
      "sendDistributeBalance",
      "sendTreasuryBalance"
    ],
    "nesting_bound": {
      "sendTreasuryBalance": 1
    }
  },
  "phases": {
    "function": "sendTreasuryBalance",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "exit"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "The amount of ETH in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "distributeBalance + treasuryBalance + liquidityBalance + inFlight <= _ethBal",
    "stable_formula": "distributeBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "distributeBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of balances, including any in-flight amount, does not exceed the ETH balance."
  }
}
